#include <Servo.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <QMC5883LCompass.h>
#include <EEPROM.h>
Servo servoHorizontal;
Servo servoVertical;
LiquidCrystal_I2C lcd(0x27, 16, 2);
QMC5883LCompass compass;
// Пины
const int JOY_X = A0;
const int JOY_Y = A1;
const int JOY_BTN = 2;
const int LED_STATUS = 13;
const int SERVO_H = 9;
const int SERVO_V = 10;
// Переменные
int angleHorizontal = 90;
int angleVertical = 90;
int azimuth = 0;
// Целевые значения (память)
int targetAzimuth = 0;
int targetHorizontal = 90;
int targetVertical = 90;
bool hasMemory = false; // Есть ли сохраненная позиция
bool stabilizationMode = false; // Режим стабилизации активен
// Кнопка
bool lastBtnState = HIGH;
unsigned long lastDebounce = 0;
const unsigned long DEBOUNCE_DELAY = 50;
unsigned long btnPressStart = 0;
bool longPressHandled = false;
// Адреса в EEPROM
const int EEPROM_MAGIC = 0; // Метка наличия данных
const int EEPROM_AZ = 2;
const int EEPROM_H = 4;
const int EEPROM_V = 6;
const int EEPROM_MAGIC_VALUE = 0xAB;
// Стабилизация
const int AZIMUTH_TOLERANCE = 3; // Допуск в градусах
const int CORRECTION_SPEED = 1; // Скорость коррекции
const int MAX_CORRECTION = 30; // Максимальная коррекция от цели
// Тайминги
unsigned long lastUpdate = 0;
const int UPDATE_INTERVAL = 50;
void setup() {
Serial.begin(9600);
pinMode(JOY_BTN, INPUT_PULLUP);
pinMode(LED_STATUS, OUTPUT);
servoHorizontal.attach(SERVO_H);
servoVertical.attach(SERVO_V);
lcd.init();
lcd.backlight();
lcd.clear();
lcd.print("Init...");
compass.init();
delay(500);
// Загружаем сохраненную позицию из EEPROM
loadMemory();
// Устанавливаем начальные углы
if (hasMemory) {
angleHorizontal = targetHorizontal;
angleVertical = targetVertical;
lcd.clear();
lcd.print("Memory loaded");
delay(1000);
}
servoHorizontal.write(angleHorizontal);
servoVertical.write(angleVertical);
updateDisplay();
}
void loop() {
unsigned long now = millis();
// Обработка кнопки (короткое и длинное нажатие)
handleButton();
// Обновление каждые UPDATE_INTERVAL мс
if (now - lastUpdate >= UPDATE_INTERVAL) {
lastUpdate = now;
// Читаем компас
compass.read();
azimuth = compass.getAzimuth();
// Читаем джойстик
int joyX = analogRead(JOY_X);
int joyY = analogRead(JOY_Y);
// Если джойстик двигают — выходим из режима стабилизации
if (abs(joyX - 512) > 100 || abs(joyY - 512) > 100) {
if (stabilizationMode) {
stabilizationMode = false;
digitalWrite(LED_STATUS, LOW);
}
}
if (stabilizationMode) {
// РЕЖИМ СТАБИЛИЗАЦИИ - автокоррекция
stabilizePlatform();
} else {
// РУЧНОЕ УПРАВЛЕНИЕ джойстиком
manualControl(joyX, joyY);
}
// Применяем углы к сервоприводам
servoHorizontal.write(angleHorizontal);
servoVertical.write(angleVertical);
updateDisplay();
}
}
// ==================== РУЧНОЕ УПРАВЛЕНИЕ ====================
void manualControl(int joyX, int joyY) {
if (joyX < 400) {
angleHorizontal = constrain(angleHorizontal - 2, 0, 180);
} else if (joyX > 600) {
angleHorizontal = constrain(angleHorizontal + 2, 0, 180);
}
if (joyY < 400) {
angleVertical = constrain(angleVertical - 2, 0, 180);
} else if (joyY > 600) {
angleVertical = constrain(angleVertical + 2, 0, 180);
}
}
// ==================== СТАБИЛИЗАЦИЯ ====================
void stabilizePlatform() {
// Разница между текущим и целевым азимутом
int diff = targetAzimuth - azimuth;
// Нормализация разницы в диапазон -180..180
if (diff > 180) diff -= 360;
if (diff < -180) diff += 360;
// Если отклонение больше допуска — корректируем
if (abs(diff) > AZIMUTH_TOLERANCE) {
// Проверяем, не вышли ли за пределы максимальной коррекции
int correction = angleHorizontal - targetHorizontal;
if (abs(correction) < MAX_CORRECTION) {
// Определяем направление коррекции
if (diff > 0) {
angleHorizontal = constrain(angleHorizontal + CORRECTION_SPEED, 0, 180);
} else {
angleHorizontal = constrain(angleHorizontal - CORRECTION_SPEED, 0, 180);
}
}
}
// Вертикаль возвращаем к сохраненному значению
if (angleVertical < targetVertical) {
angleVertical = constrain(angleVertical + CORRECTION_SPEED, 0, 180);
} else if (angleVertical > targetVertical) {
angleVertical = constrain(angleVertical - CORRECTION_SPEED, 0, 180);
}
}
// ==================== ОБРАБОТКА КНОПКИ ====================
void handleButton() {
bool btnState = digitalRead(JOY_BTN);
unsigned long now = millis();
// Антидребезг
if (btnState != lastBtnState) {
lastDebounce = now;
}
if ((now - lastDebounce) > DEBOUNCE_DELAY) {
// Кнопка только что нажата
if (btnState == LOW && lastBtnState == HIGH) {
btnPressStart = now;
longPressHandled = false;
}
// Кнопка удерживается
if (btnState == LOW && !longPressHandled) {
if ((now - btnPressStart) > 1500) {
// ДЛИННОЕ НАЖАТИЕ — сброс памяти
clearMemory();
longPressHandled = true;
}
}
// Кнопка отпущена
if (btnState == HIGH && lastBtnState == LOW) {
if (!longPressHandled && (now - btnPressStart) > 50) {
// КОРОТКОЕ НАЖАТИЕ — сохранение позиции
savePosition();
}
}
}
lastBtnState = btnState;
}
// ==================== СОХРАНЕНИЕ ПОЗИЦИИ ====================
void savePosition() {
// Читаем актуальный азимут
compass.read();
targetAzimuth = compass.getAzimuth();
targetHorizontal = angleHorizontal;
targetVertical = angleVertical;
hasMemory = true;
// Записываем в EEPROM
EEPROM.write(EEPROM_AZ, targetAzimuth);
EEPROM.write(EEPROM_H, targetHorizontal);
EEPROM.write(EEPROM_V, targetVertical);
EEPROM.write(EEPROM_MAGIC, EEPROM_MAGIC_VALUE);
// Включаем режим стабилизации
stabilizationMode = true;
digitalWrite(LED_STATUS, HIGH);
// Индикация
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("SAVED!");
lcd.setCursor(0, 1);
lcd.print("Az:");
lcd.print(targetAzimuth);
lcd.print(" H:");
lcd.print(targetHorizontal);
Serial.print("Position saved! Azimuth: ");
Serial.print(targetAzimuth);
Serial.print(" H: ");
Serial.print(targetHorizontal);
Serial.print(" V: ");
Serial.println(targetVertical);
delay(1000);
}
// ==================== ЗАГРУЗКА ИЗ EEPROM ====================
void loadMemory() {
if (EEPROM.read(EEPROM_MAGIC) == EEPROM_MAGIC_VALUE) {
targetAzimuth = EEPROM.read(EEPROM_AZ);
targetHorizontal = EEPROM.read(EEPROM_H);
targetVertical = EEPROM.read(EEPROM_V);
// Проверка на корректность значений
if (targetAzimuth >= 0 && targetAzimuth <= 359 &&
targetHorizontal >= 0 && targetHorizontal <= 180 &&
targetVertical >= 0 && targetVertical <= 180) {
hasMemory = true;
Serial.println("Memory loaded from EEPROM");
} else {
hasMemory = false;
}
} else {
hasMemory = false;
}
}
// ==================== СБРОС ПАМЯТИ ====================
void clearMemory() {
EEPROM.write(EEPROM_MAGIC, 0);
hasMemory = false;
stabilizationMode = false;
digitalWrite(LED_STATUS, LOW);
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("MEMORY CLEARED");
Serial.println("Memory cleared!");
delay(1000);
}
// ==================== ДИСПЛЕЙ ====================
void updateDisplay() {
lcd.clear();
// Первая строка: азимут и режим
lcd.setCursor(0, 0);
lcd.print("Az:");
lcd.print(azimuth);
lcd.print((char)223); // символ градуса
lcd.print(" ");
if (stabilizationMode) {
lcd.print("LOCK");
} else if (hasMemory) {
lcd.print("MEM ");
} else {
lcd.print("FREE");
}
// Вторая строка: углы и цель
lcd.setCursor(0, 1);
lcd.print("H:");
lcd.print(angleHorizontal);
lcd.print(" V:");
lcd.print(angleVertical);
if (hasMemory) {
lcd.print(" T:");
lcd.print(targetAzimuth);
}
}
